CREATE OR REPLACE FUNCTION contains_zip(zip_code text, delivery_zones text) RETURNS boolean AS $$
DECLARE
    zone_elements text[];
    start_zone int;
    end_zone int;
BEGIN
    -- Split the delivery zones by commas
    zone_elements := string_to_array(delivery_zones, ',');

    FOR i IN array_lower(zone_elements, 1)..array_upper(zone_elements, 1) LOOP
        -- Check if the current element is a range
        IF position('-' in zone_elements[i]) > 0 THEN
            -- Extract start and end of the range
            start_zone := cast(split_part(zone_elements[i], '-', 1) as int);
            end_zone := cast(split_part(zone_elements[i], '-', 2) as int);

            -- Check if the zip_code is within the range
            IF zip_code::int >= start_zone AND zip_code::int <= end_zone THEN
                RETURN true;
            END IF;
        ELSE
            -- Direct comparison for non-range elements
            IF zone_elements[i] = zip_code THEN
                RETURN true;
            END IF;
        END IF;
    END LOOP;

    RETURN false;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

